import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import ImageWithFallback from "@/components/image-with-fallback";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { pageHead } from "@/utils/page-head";
import { trpc } from "@/utils/trpc";
import { useQuery } from "@tanstack/react-query";
import { createFileRoute, Link, redirect } from "@tanstack/react-router";
import {
  BookOpen,
  ChevronRight,
  Clock,
  CreditCard,
  Package,
  ShoppingBag,
} from "lucide-react";
import { authMeQueryOptions } from "@/utils/auth-query";
import z from "zod";

export const Route = createFileRoute("/pelatihan/transaksi/")({
  validateSearch: z.object({
    status: z.string().optional(),
  }),
  beforeLoad: async ({ context }) => {
    try {
      const user =
        await context.queryClient.ensureQueryData(authMeQueryOptions());
      if (!user) {
        throw redirect({
          to: "/login",
          search: { redirect: "/pelatihan/transaksi" },
        });
      }
    } catch (error) {
      if (error && typeof error === "object" && "isRedirect" in error) {
        throw error;
      }
      throw redirect({
        to: "/login",
        search: { redirect: "/pelatihan/transaksi" },
      });
    }
  },
  head: () => pageHead("Transaksi Pelatihan"),
  component: RouteComponent,
});

const ORDER_STATUS_LABELS: Record<string, string> = {
  pending: "Menunggu Pembayaran",
  waiting_verification: "Menunggu Verifikasi",
  verified: "Terverifikasi",
  cancelled: "Dibatalkan",
  expired: "Kadaluarsa",
};

const PAYMENT_STATUS_LABELS: Record<string, string> = {
  unpaid: "Belum Bayar",
  pending: "Menunggu Konfirmasi",
  paid: "Sudah Dibayar",
  refunded: "Dikembalikan",
};

const ORDER_STATUS_VARIANTS: Record<
  string,
  "default" | "secondary" | "destructive" | "outline"
> = {
  pending: "secondary",
  waiting_verification: "outline",
  verified: "default",
  cancelled: "destructive",
  expired: "destructive",
};

const STATUS_FILTERS = [
  { label: "Semua", value: "all" },
  { label: "Menunggu Bayar", value: "pending" },
  { label: "Verifikasi", value: "waiting_verification" },
  { label: "Terverifikasi", value: "verified" },
  { label: "Dibatalkan", value: "cancelled" },
];

function TransaksiSkeleton() {
  return (
    <div className="space-y-4">
      {[1, 2, 3].map((i) => (
        <Card key={i}>
          <CardHeader className="pb-3">
            <Skeleton className="h-5 w-40" />
            <Skeleton className="h-4 w-24" />
          </CardHeader>
          <CardContent>
            <Skeleton className="h-16 w-full" />
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

function RouteComponent() {
  const { status } = Route.useSearch();
  const navigate = Route.useNavigate();

  const { data: orders, isLoading } = useQuery(
    trpc.pelatihan.order.getUserOrders.queryOptions(),
  );

  const filtered =
    !status || status === "all"
      ? orders
      : orders?.filter((o) => o.status === status);

  return (
    <div className="mx-auto max-w-3xl px-4 py-8 sm:px-0">
      {/* Header */}
      <div className="mb-6">
        <h1 className="mb-1 text-xl font-bold text-foreground sm:text-2xl">
          Transaksi Pelatihan
        </h1>
        <p className="text-sm text-muted-foreground">
          Kelola dan pantau status pembelian kelas pelatihan Anda
        </p>
      </div>

      {/* Filters */}
      <Tabs
        value={status ?? "all"}
        onValueChange={(value) => {
          navigate({
            to: "/pelatihan/transaksi",
            search: { status: value === "all" ? undefined : value },
          });
        }}
        className="mb-6"
      >
        <div className="-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0">
          <TabsList className="inline-flex w-max bg-white sm:w-auto">
            {STATUS_FILTERS.map((s) => (
              <TabsTrigger
                key={s.value}
                value={s.value}
                className="text-xs whitespace-nowrap data-[state=active]:bg-primary data-[state=active]:text-primary-foreground data-[state=active]:shadow-sm sm:text-sm"
              >
                {s.label}
              </TabsTrigger>
            ))}
          </TabsList>
        </div>
      </Tabs>

      {/* List */}
      {isLoading ? (
        <TransaksiSkeleton />
      ) : !filtered || filtered.length === 0 ? (
        <div className="flex h-64 flex-col items-center justify-center rounded-xl border border-dashed bg-card">
          <div className="mb-4 rounded-full bg-primary/10 p-4">
            <ShoppingBag className="h-8 w-8 text-primary" />
          </div>
          <p className="text-lg font-medium">Belum ada transaksi</p>
          <p className="mb-6 max-w-xs text-center text-sm text-muted-foreground">
            Anda belum melakukan pembelian kelas. Yuk mulai belajar!
          </p>
          <Button asChild>
            <Link to="/pelatihan">Jelajahi Kelas</Link>
          </Button>
        </div>
      ) : (
        <div className="space-y-4">
          {filtered.map((order) => (
            <Link
              key={order.id}
              to="/pelatihan/transaksi/$orderId"
              params={{ orderId: order.id }}
            >
              <Card className="group cursor-pointer transition-all hover:border-primary/30 hover:shadow-md">
                <CardHeader className="pb-2">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <CardTitle className="text-base font-semibold transition-colors group-hover:text-primary">
                        {order.orderNumber}
                      </CardTitle>
                      <CardDescription className="mt-0.5 flex items-center gap-1">
                        <Clock className="h-3 w-3" />
                        {new Date(order.createdAt).toLocaleDateString("id-ID", {
                          day: "numeric",
                          month: "long",
                          year: "numeric",
                        })}
                      </CardDescription>
                    </div>
                    <div className="flex flex-col items-end gap-1">
                      <Badge
                        variant={
                          ORDER_STATUS_VARIANTS[order.status] ?? "secondary"
                        }
                      >
                        {ORDER_STATUS_LABELS[order.status] ?? order.status}
                      </Badge>
                      <span className="text-xs text-muted-foreground">
                        {PAYMENT_STATUS_LABELS[order.paymentStatus] ??
                          order.paymentStatus}
                      </span>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="space-y-2">
                    {order.items.slice(0, 2).map((item) => (
                      <div key={item.id} className="flex items-center gap-3">
                        <div className="h-10 w-14 flex-shrink-0 overflow-hidden rounded-md bg-muted">
                          {item.pelatihan.thumbnailUrl ? (
                            <ImageWithFallback
                              src={item.pelatihan.thumbnailUrl}
                              alt={item.pelatihan.title}
                              className="h-full w-full object-cover"
                            />
                          ) : (
                            <div className="flex h-full w-full items-center justify-center">
                              <BookOpen className="h-4 w-4 text-muted-foreground/50" />
                            </div>
                          )}
                        </div>
                        <p className="line-clamp-1 flex-1 text-sm font-medium">
                          {item.pelatihan.title}
                        </p>
                      </div>
                    ))}
                    {order.items.length > 2 && (
                      <p className="flex items-center gap-1 text-xs text-muted-foreground">
                        <Package className="h-3 w-3" />+{order.items.length - 2}{" "}
                        kelas lainnya
                      </p>
                    )}
                  </div>

                  <div className="mt-3 flex items-center justify-between border-t pt-3">
                    <div className="flex items-center gap-1.5 text-sm text-muted-foreground">
                      <CreditCard className="h-4 w-4" />
                      <span className="font-semibold text-foreground">
                        Rp {order.totalAmount.toLocaleString("id-ID")}
                      </span>
                    </div>
                    <ChevronRight className="h-4 w-4 text-muted-foreground transition-colors group-hover:text-primary" />
                  </div>
                </CardContent>
              </Card>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}

